import joblib
import pandas as pd

# Load the saved Random Forest
risk_model = joblib.load("zenith_model.pkl")

# Load the anomaly results generated by our existing script.
# For now, recreate the anomaly detector using the same features.
from anomaly_detection import IsolationForest, features, X

anomaly_model = IsolationForest(
    n_estimators=200,
    contamination=0.10,
    random_state=42
)

anomaly_model.fit(X)

features["anomaly_score"] = anomaly_model.decision_function(X)
features["anomaly_prediction"] = anomaly_model.predict(X)

features["anomaly_status"] = features["anomaly_prediction"].map({
    1: "NORMAL",
    -1: "ANOMALY"
})

# Predict risk category using Random Forest
features["predicted_triage"] = risk_model.predict(X)

# Combine the results
results = features[
    ["chip_id", "predicted_triage", "anomaly_score", "anomaly_status"]
].copy()

# Sort the most anomalous chips to the top
results = results.sort_values("anomaly_score")

print("\nCOMBINED MODEL RESULTS:")
print(results.head(20).to_string(index=False))

print("\nRISK CATEGORY VS ANOMALY STATUS:")
print(
    pd.crosstab(
        results["predicted_triage"],
        results["anomaly_status"]
    )
)